INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130011, 3001100, 3001, 1, 2.1, "ヤマト", -416.5, 0.0, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", "2030/01/01 14:59:59", 2, "2024/10/31 12:00:00", 100);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130011, 3001101, 3001, 4, 5.68, "ヤマト", -416.5, 0.0, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", "2030/01/01 14:59:59", 2, "2024/10/31 12:00:00", 101);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130011, 3001102, 3001, 1, 0.0, "ヤマト", -416.5, 0.0, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", "2030/01/01 14:59:59", 1, "2024/10/31 12:00:00", 102);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3002100, 3002, 1, 0.0, "フブキ", -416.5, 0.0, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", "2030/01/01 14:59:59", 1, "2024/10/31 12:00:00", 100);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3002101, 3002, 1, 0.0, "フブキ", -416.5, 0.0, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", "2030/01/01 14:59:59", 1, "2024/10/31 12:00:00", 101);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3002102, 3002, 5, 8.53, "フブキ", -416.5, 0.0, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", "2030/01/01 14:59:59", 2, "2024/10/31 12:00:00", 102);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3002103, 3002, 7, 5.67, "フブキ", -416.5, 0.0, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", "2030/01/01 14:59:59", 1, "2024/10/31 12:00:00", 103);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3002104, 3002, 1, 0.0, "フブキ", -416.5, 0.0, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", "2030/01/01 14:59:59", 1, "2024/10/31 12:00:00", 104);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3002300, 3004, 3, 0.0, "フブキ", -416.5, 0.0, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", "2030/01/01 14:59:59", 3, "2024/10/31 12:00:00", 300);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3002400, 3005, 7, 0.0, "フブキ", -416.5, 0.0, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", "2030/01/01 14:59:59", 7, "2024/10/31 12:00:00", 301);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3003200, 3003, 2, 4.4, "フブキ", -416.5, 0.0, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", "2030/01/01 14:59:59", 1, "2024/10/31 12:00:00", 200);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3003201, 3003, 7, 0.0, "フブキ", -416.5, 0.0, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", "2030/01/01 14:59:59", 7, "2024/10/31 12:00:00", 201);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES (130211, 3003202, 3003, 1, 5.6, "フブキ", -416.5, 0.0, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", "2030/01/01 14:59:59", 2, "2024/10/31 12:00:00", 202);
